import{_ as e,o as d,c as o,a5 as r}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"DA-D12-03 — [R3 §3.1.5] ERD Entity Descriptions V2","description":"","frontmatter":{},"headers":[],"relativePath":"database/schema-v2/erd-entity-descriptions.md","filePath":"database/schema-v2/erd-entity-descriptions.md"}'),a={name:"database/schema-v2/erd-entity-descriptions.md"};function n(c,t,i,s,h,l){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="da-d12-03-—-r3-§3-1-5-erd-entity-descriptions-v2" tabindex="-1">DA-D12-03 — [R3 §3.1.5] ERD Entity Descriptions V2 <a class="header-anchor" href="#da-d12-03-—-r3-§3-1-5-erd-entity-descriptions-v2" aria-label="Permalink to &quot;DA-D12-03 — [R3 §3.1.5] ERD Entity Descriptions V2&quot;">​</a></h1><p>&gt; <strong>STATUS: DESIGN</strong> — schema mới cho nghiệp vụ V2 (Agency → Workspace → Media Package → Media Campaign → Task), chưa áp dụng vào <code>scripts/init-postgres.sql</code> thật. &gt; <strong>Owner:</strong> Trung | <strong>Priority:</strong> 🟡 Medium &gt; <strong>Nguồn:</strong> <code>docs/BA/11-data-entities-glossary.md</code>, <code>docs/database/schema-v2/database-strategy.md</code> &gt; <strong>Source ERD:</strong> <a href="./brandhub-erd.puml.html"><code>brandhub-erd.puml</code></a> · <a href="./brandhub-dbml.dbml.html"><code>brandhub-dbml.dbml</code></a> · <a href="./brandhub-schema-diagram.html"><code>brandhub-schema-diagram.html</code></a></p><hr><h2 id="_1-erd-figure" tabindex="-1">1. ERD Figure <a class="header-anchor" href="#_1-erd-figure" aria-label="Permalink to &quot;1. ERD Figure&quot;">​</a></h2><p>&gt; Render <code>brandhub-erd.puml</code> (PlantUML) hoặc mở <code>brandhub-schema-diagram.html</code> cho interactive schema diagram.</p><hr><h2 id="_2-entity-descriptions" tabindex="-1">2. Entity Descriptions <a class="header-anchor" href="#_2-entity-descriptions" aria-label="Permalink to &quot;2. Entity Descriptions&quot;">​</a></h2><p>BrandHub V2&#39;s ERD chứa <strong>37 entity</strong>: <strong>23 PostgreSQL</strong> tables (identity, tổ chức Agency/Workspace, thương mại Package/Campaign, Third-party Collaborator, billing) và <strong>14 MongoDB</strong> collections (Task/content thực thi, operational data — cập nhật 2026-09-16: +livestream_sessions, +survey_forms, +survey_responses, +mail_templates). Xem <a href="./database-strategy.html"><code>database-strategy.md</code></a> cho storage-split rationale và các quyết định thiết kế.</p><h3 id="_2-1-postgresql-—-identity-group-4-tables-khong-đoi-so-voi-v1" tabindex="-1">2.1 PostgreSQL — Identity Group (4 tables, không đổi so với V1) <a class="header-anchor" href="#_2-1-postgresql-—-identity-group-4-tables-khong-đoi-so-voi-v1" aria-label="Permalink to &quot;2.1 PostgreSQL — Identity Group (4 tables, không đổi so với V1)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Entity</th><th>Description</th></tr></thead><tbody><tr><td>1</td><td><code>users</code></td><td>Core user account: credentials, profile, status. Anchor cho mọi identity FK.</td></tr><tr><td>2</td><td><code>user_oauth_providers</code></td><td>Liên kết user với OAuth identity ngoài (Google, Facebook).</td></tr><tr><td>3</td><td><code>user_refresh_tokens</code></td><td>Refresh token active theo device/session.</td></tr><tr><td>4</td><td><code>user_system_roles</code></td><td>Role hệ thống (<code>ADMIN</code>/<code>USER</code>), tách biệt khỏi role theo Workspace.</td></tr></tbody></table><h3 id="_2-2-postgresql-—-organization-group-8-tables-moi-đoi-v2" tabindex="-1">2.2 PostgreSQL — Organization Group (8 tables, MỚI/ĐỔI V2) <a class="header-anchor" href="#_2-2-postgresql-—-organization-group-8-tables-moi-đoi-v2" aria-label="Permalink to &quot;2.2 PostgreSQL — Organization Group (8 tables, MỚI/ĐỔI V2)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Entity</th><th>Trạng thái</th><th>Description</th></tr></thead><tbody><tr><td>5</td><td><code>agencies</code></td><td><strong>MỚI</strong></td><td>Công ty truyền thông, anchor mới của toàn bộ chain. Mỗi Agency đúng 1 Owner.</td></tr><tr><td>6</td><td><code>agency_members</code></td><td><strong>MỚI</strong></td><td>Junction User↔Agency, KHÔNG có cột role.</td></tr><tr><td>7</td><td><code>agency_invitations</code></td><td><strong>MỚI</strong></td><td>Lời mời vào Agency, hết hạn 3 ngày.</td></tr><tr><td>8</td><td><code>workspaces</code></td><td><strong>ĐỔI</strong></td><td>Thuộc 1 Agency (FK thật), phục vụ nhiều Client. Owner suy ra qua <code>agency.owner_id</code>.</td></tr><tr><td>9</td><td><code>workspace_members</code></td><td><strong>ĐỔI</strong></td><td>Role theo TỪNG Workspace (<code>OWNER</code>/<code>MANAGER</code>/<code>CREATOR</code>/<code>CLIENT</code>) — gộp Client vào đây, thay bảng <code>clients</code> V1.</td></tr><tr><td>10</td><td><code>workspace_invitations</code></td><td>Không đổi</td><td>Lời mời vào Workspace.</td></tr><tr><td>11</td><td><code>workspace_templates</code></td><td><strong>MỚI</strong></td><td>Lưu cấu hình Workspace để tái sử dụng khi tạo Workspace mới.</td></tr><tr><td>12</td><td><code>client_profiles</code></td><td><strong>MỚI</strong></td><td>Profile riêng của Client, tái sử dụng xuyên nhiều Agency/Workspace. Email cố định (FR 3.3.4).</td></tr></tbody></table><h3 id="_2-3-postgresql-—-commerce-group-3-tables-moi-hoan-toan-v2" tabindex="-1">2.3 PostgreSQL — Commerce Group (3 tables, MỚI hoàn toàn V2) <a class="header-anchor" href="#_2-3-postgresql-—-commerce-group-3-tables-moi-hoan-toan-v2" aria-label="Permalink to &quot;2.3 PostgreSQL — Commerce Group (3 tables, MỚI hoàn toàn V2)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Entity</th><th>Description</th></tr></thead><tbody><tr><td>13</td><td><code>media_packages</code></td><td>Package mẫu (Admin tạo) hoặc custom (Owner/Manager tạo), gộp 1 bảng qua cột <code>is_template</code>.</td></tr><tr><td>14</td><td><code>workspace_media_packages</code></td><td>Package đã áp dụng + đàm phán cho 1 Workspace cụ thể — ACID 2-bên-approve.</td></tr><tr><td>15</td><td><code>media_campaigns</code></td><td>Kế hoạch thực thi chi tiết, sinh từ Package đã approve. Immutable sau approve.</td></tr></tbody></table><h3 id="_2-4-postgresql-—-third-party-collaborator-group-2-tables-moi-hoan-toan-v2" tabindex="-1">2.4 PostgreSQL — Third-party Collaborator Group (2 tables, MỚI hoàn toàn V2) <a class="header-anchor" href="#_2-4-postgresql-—-third-party-collaborator-group-2-tables-moi-hoan-toan-v2" aria-label="Permalink to &quot;2.4 PostgreSQL — Third-party Collaborator Group (2 tables, MỚI hoàn toàn V2)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Entity</th><th>Description</th></tr></thead><tbody><tr><td>16</td><td><code>third_party_collaborators</code></td><td>Danh bạ đối tác truyền thông ngoài (báo/banner/TV) cấp Agency, tái sử dụng qua nhiều Campaign.</td></tr><tr><td>17</td><td><code>campaign_collaborators</code></td><td>Bảng liên kết N-N — trạng thái hợp tác (<code>contacted</code>/<code>negotiating</code>/<code>confirmed</code>/<code>live</code>) theo TỪNG Campaign.</td></tr></tbody></table><h3 id="_2-5-postgresql-—-billing-group-6-tables-đoi-pham-vi-gan-plan" tabindex="-1">2.5 PostgreSQL — Billing Group (6 tables, đổi phạm vi gắn Plan) <a class="header-anchor" href="#_2-5-postgresql-—-billing-group-6-tables-đoi-pham-vi-gan-plan" aria-label="Permalink to &quot;2.5 PostgreSQL — Billing Group (6 tables, đổi phạm vi gắn Plan)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Entity</th><th>Trạng thái</th><th>Description</th></tr></thead><tbody><tr><td>18</td><td><code>subscription_plans</code></td><td>Không đổi</td><td>Catalog gói (Basic/Pro/Enterprise).</td></tr><tr><td>19</td><td><code>user_subscriptions</code></td><td><strong>ĐỔI TÊN</strong></td><td>Từ <code>workspace_subscriptions</code> — Plan gắn cấp <strong>User/Owner</strong>, áp dụng toàn bộ Agency của họ.</td></tr><tr><td>20</td><td><code>transactions</code></td><td><strong>ĐỔI TÊN</strong></td><td>Từ <code>payments</code>, gộp <code>invoices</code> — giao dịch PayOS, ACID.</td></tr><tr><td>21</td><td><code>ai_credit_ledgers</code></td><td><strong>MỚI</strong></td><td>Sổ credit AI theo tháng, reset hàng tháng, KHÔNG rollover.</td></tr><tr><td>22</td><td><code>ai_credit_creator_limits</code></td><td><strong>MỚI 2026-09-16</strong></td><td>Cấu hình giới hạn credit RIÊNG từng Creator (Owner set), chỉ config — usage thật đọc từ <code>ai_usage_logs</code>.</td></tr><tr><td>—</td><td><code>audit_logs</code></td><td>Không đổi</td><td>Append-only, log hành động nhạy cảm.</td></tr></tbody></table><h3 id="_2-6-mongodb-collections-16-collections" tabindex="-1">2.6 MongoDB Collections (16 collections) <a class="header-anchor" href="#_2-6-mongodb-collections-16-collections" aria-label="Permalink to &quot;2.6 MongoDB Collections (16 collections)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Entity</th><th>Trạng thái</th><th>Description</th></tr></thead><tbody><tr><td>23</td><td><code>tasks</code></td><td><strong>MỚI</strong>, thay <code>posts</code> V1</td><td>Đơn vị công việc chung 5 loại (POST/LIVESTREAM/SURVEY/EVENT_PLAN/PRESS_RECOMMENDATION), dùng chung Approval Sequence.</td></tr><tr><td>24</td><td><code>task_approvals</code></td><td><strong>MỚI</strong>, tách khỏi <code>tasks</code></td><td>Lịch sử duyệt theo từng step — giữ nguyên approval cũ khi step sau bị reject.</td></tr><tr><td>25</td><td><code>posts</code></td><td><strong>ĐỔI NGHĨA</strong></td><td>Chỉ còn bài ĐÃ PUBLISH thành công lên social (kết quả Task type=post hoàn thành).</td></tr><tr><td>26</td><td><code>content_requests</code></td><td><strong>ĐỔI FSM</strong></td><td><code>pending → in_progress → accepted/denied</code>, <code>denied</code> là trạng thái terminal.</td></tr><tr><td>27</td><td><code>material_repository</code></td><td><strong>MỚI</strong></td><td>Kho ảnh/video, phân biệt raw vs đã retouch.</td></tr><tr><td>28</td><td><code>brand_collections</code></td><td><strong>MỚI</strong></td><td>Tài liệu Client cung cấp làm tham khảo.</td></tr><tr><td>29</td><td><code>hashtag_collections</code></td><td><strong>MỚI</strong></td><td>Kho hashtag theo Workspace.</td></tr><tr><td>30</td><td><code>content_versions</code></td><td><strong>MỚI</strong></td><td>Lịch sử version nội dung (Content History).</td></tr><tr><td>31</td><td><code>livestream_sessions</code></td><td><strong>MỚI 2026-09-16</strong></td><td>Con của Task loại livestream — idea/script/status (FR 3.6.22-24).</td></tr><tr><td>32</td><td><code>survey_forms</code></td><td><strong>MỚI 2026-09-16</strong></td><td>Con của Task loại survey — form câu hỏi (FR 3.6.25).</td></tr><tr><td>33</td><td><code>survey_responses</code></td><td><strong>MỚI 2026-09-16</strong></td><td>Câu trả lời khảo sát, tách riêng vì high write throughput.</td></tr><tr><td>34</td><td><code>mail_templates</code></td><td><strong>MỚI 2026-09-16, SỬA 2026-10-12</strong></td><td>Mẫu email theo Workspace + mẫu hệ thống (<code>workspaceId</code> null, Admin quản trị); có <code>attachments</code>, <code>clonedFromId</code>, soft delete <code>deletedAt</code> (FR 3.6.28-32).</td></tr><tr><td>35</td><td><code>social_accounts</code></td><td>Giữ nguyên, bỏ <code>ZALO_OA</code></td><td>Tài khoản social đã connect (Facebook/Instagram/TikTok/Threads).</td></tr><tr><td>36</td><td><code>notifications</code></td><td>Giữ nguyên, thêm type mới</td><td>Thông báo, thêm loại cho Package/Campaign/Task approval.</td></tr><tr><td>37</td><td><code>event_plans</code></td><td><strong>MỚI DA-948</strong></td><td>Nội dung kế hoạch bàn giao của Task EVENT_PLAN; không phải module vận hành sự kiện.</td></tr><tr><td>38</td><td><code>press_recommendations</code></td><td><strong>MỚI DA-948</strong></td><td>Gợi ý bên báo chí của Task PRESS_RECOMMENDATION; không phải booking tích hợp.</td></tr></tbody></table><hr><h3 id="_2-7-postgresql-—-mail-sending-group-5-tables-moi-2026-10-12-fr-3-6-32" tabindex="-1">2.7 PostgreSQL — Mail Sending Group (5 tables, MỚI 2026-10-12, FR 3.6.32) <a class="header-anchor" href="#_2-7-postgresql-—-mail-sending-group-5-tables-moi-2026-10-12-fr-3-6-32" aria-label="Permalink to &quot;2.7 PostgreSQL — Mail Sending Group (5 tables, MỚI 2026-10-12, FR 3.6.32)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Entity</th><th>Description</th></tr></thead><tbody><tr><td>M1</td><td><code>mail_batches</code></td><td>Một lần bấm gửi/hẹn giờ/gửi thử: snapshot subject, body, đính kèm; trạng thái <code>SCHEDULED/QUEUED/SENDING/COMPLETED/CANCELLED/FAILED</code>; bộ đếm kết quả.</td></tr><tr><td>M2</td><td><code>mail_deliveries</code></td><td>Một người nhận của một lô: nội dung đã render, trạng thái <code>PENDING/SENT/FAILED/SUPPRESSED</code>, số lần thử, <code>event_key</code> idempotent. Worker lấy bằng <code>FOR UPDATE SKIP LOCKED</code>.</td></tr><tr><td>M3</td><td><code>mail_send_quota</code></td><td>Bộ đếm gửi theo ngày (<code>Asia/Ho_Chi_Minh</code>) cho phạm vi <code>SYSTEM</code> (450) và <code>WORKSPACE</code> (100).</td></tr><tr><td>M4</td><td><code>mail_suppressions</code></td><td>Người nhận đã hủy đăng ký, theo Workspace gửi; unique <code>(workspace_id, email_lower)</code>.</td></tr><tr><td>M5</td><td><code>mail_attachments</code></td><td>Tệp/ảnh upload cho template (S3 key, loại, kích thước); <code>bound=false</code> quá 24h bị job dọn.</td></tr></tbody></table><p>Các bảng này nằm cùng PostgreSQL với <code>admin_email_outbox</code> để enqueue transactional. <code>mail_batches.template_id</code> là soft reference tới <code>mail_templates</code> (MongoDB). Nội dung đã render và địa chỉ nhận bị xóa sau 12 tháng, số liệu tổng giữ lại.</p><h2 id="_3-relationship-notes" tabindex="-1">3. Relationship Notes <a class="header-anchor" href="#_3-relationship-notes" aria-label="Permalink to &quot;3. Relationship Notes&quot;">​</a></h2><p>Full FK relationship diagram nằm ở <a href="./brandhub-erd.puml.html"><code>brandhub-erd.puml</code></a>. Tóm tắt:</p><ul><li><strong>Identity chain</strong>: <code>users</code> toả FK tới <code>user_oauth_providers</code>, <code>user_refresh_tokens</code>, <code>user_system_roles</code>, và giờ còn là anchor của <code>agencies.owner_id</code>.</li><li><strong>Organization chain (MỚI)</strong>: <code>agencies</code> → <code>workspaces</code> → <code>workspace_members</code>/<code>workspace_invitations</code>/<code>ws_media_packages</code>. <code>client_profiles</code> liên kết N-N tới <code>workspace_members</code> (chỉ khi <code>role = CLIENT</code>).</li><li><strong>Commerce chain (MỚI)</strong>: <code>media_packages</code> → <code>workspace_media_packages</code> → <code>media_campaigns</code> → <code>campaign_collaborators</code> → <code>third_party_collaborators</code>.</li><li><strong>Billing chain</strong>: <code>user_subscriptions → subscription_plans</code>, <code>transactions → users</code> (không còn qua <code>invoices</code> riêng như V1).</li><li><strong>MongoDB collections</strong> dùng <strong>soft reference</strong> (string ID, không FK enforce) về <code>workspaceId</code>/<code>userId</code>/<code>clientProfileId</code> PostgreSQL — nhất quán với chiến lược đa DB, referential integrity thực thi ở application layer.</li></ul><div class="warning custom-block"><p class="custom-block-title">Ghi chú thay đổi lớn nhất</p><p>So với V1 (17 entity theo mô tả gốc cũ, thực tế tăng lên 23 entity trước khi V2), schema V2 tăng lên <strong>37 entity</strong> (23 PostgreSQL + 14 MongoDB) — chủ yếu do 3 nhóm hoàn toàn mới: Organization (Agency layer, 8 bảng), Commerce (Media Package/Campaign, 3 bảng), Third-party Collaborator (2 bảng). Đây là thiết kế <strong>DESIGN</strong>, chưa migrate vào DB thật.</p></div><h3 id="mail-recipient-groups-mongodb" tabindex="-1">mail_recipient_groups (MongoDB) <a class="header-anchor" href="#mail-recipient-groups-mongodb" aria-label="Permalink to &quot;mail_recipient_groups (MongoDB)&quot;">​</a></h3><p>Named recipient lists a Workspace sends mail to repeatedly (FR 3.6.32 follow-up).</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td>_id</td><td>ObjectId</td><td></td></tr><tr><td>workspaceId</td><td>string</td><td>owner Workspace</td></tr><tr><td>name</td><td>string(80)</td><td></td></tr><tr><td>recipients</td><td>array&lt;{email, name}&gt;</td><td>max 200, emails lower-cased and unique</td></tr><tr><td>createdBy</td><td>string</td><td>user id; only the creator or OWNER/MANAGER may delete</td></tr><tr><td>createdAt</td><td>date</td><td></td></tr></tbody></table><p>Index: <code>{workspaceId:1, name:1}</code>. Limit: 50 groups per Workspace (service rule).</p>',32)])])}const m=e(a,[["render",n]]);export{p as __pageData,m as default};
